input.command:
cat > eas.json <<'EOF'
{
  "cli": {
    "version": ">= 16.0.0",
    "appVersionSource": "remote"
  },
  "build": {
    "development": {
      "developmentClient": true,
      "distribution": "internal"
    },
    "preview": {
      "distribution": "internal",
      "android": {
        "buildType": "apk"
      }
    },
    "production": {
      "autoIncrement": true
    }
  },
  "submit": {
    "production": {
      "ios": {
        "ascAppId": "TODO_REPLACE_WITH_APP_STORE_CONNECT_APP_ID"
      },
      "android": {
        "serviceAccountKeyPath": "./google-service-account.json",
        "track": "internal"
      }
    }
  }
}
EOF
python3 - <<'EOF'
import json
p='app.json'; d=json.load(open(p)); e=d['expo']
e['ios'].pop('buildNumber',None)
e['ios']['config']={'usesNonExemptEncryption': False}
a=e['android']; a.pop('versionCode',None)
e['android']={'package':'com.acmeapps.tidy', **a}
open(p,'w').write(json.dumps(d,indent=2)+'\n')
EOF
printf '\n# Google Play service account key (used by eas submit) - never commit\ngoogle-service-account.json\n' >> .gitignore
git diff

